CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version, applied_at) VALUES(1, strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,state_version INTEGER NOT NULL,state_digest TEXT NOT NULL,retention_profile TEXT NOT NULL,active_workstream_id TEXT,policy_profile TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workstreams(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,status TEXT NOT NULL,objective_state_id TEXT,created_state_version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS provider_sessions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),workstream_id TEXT,provider TEXT NOT NULL,conversation_key_hash TEXT NOT NULL,adapter_version TEXT NOT NULL,parent_session_id TEXT,fork_state_version INTEGER NOT NULL,attached_at TEXT NOT NULL,detached_at TEXT);
CREATE TABLE IF NOT EXISTS turns(id TEXT PRIMARY KEY,session_id TEXT,project_id TEXT NOT NULL REFERENCES projects(id),workstream_id TEXT,role TEXT NOT NULL,ordinal INTEGER NOT NULL,normalized_text TEXT,content_hash TEXT NOT NULL,packet_digest TEXT,completeness TEXT NOT NULL,captured_at TEXT NOT NULL,provider_timestamp TEXT,UNIQUE(session_id,ordinal,content_hash));
CREATE TABLE IF NOT EXISTS anchors(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),workstream_id TEXT,source_kind TEXT NOT NULL,source_id TEXT NOT NULL,content_hash TEXT NOT NULL,structural_signature_json TEXT NOT NULL,provenance_json TEXT NOT NULL,integrity_status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_objects(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),workstream_id TEXT,type TEXT NOT NULL,title TEXT NOT NULL,canonical_text TEXT NOT NULL,status TEXT NOT NULL,authority TEXT NOT NULL,confidence REAL NOT NULL,binding_strength TEXT,source_json TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,effective_at TEXT NOT NULL,supersedes_id TEXT,state_version INTEGER NOT NULL,object_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_edges(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),from_state_id TEXT NOT NULL,edge_type TEXT NOT NULL,to_state_id TEXT NOT NULL,created_event_id TEXT NOT NULL,edge_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,locator TEXT NOT NULL,content_hash TEXT NOT NULL,integrity_status TEXT NOT NULL,metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_events(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),event_type TEXT NOT NULL,actor_type TEXT NOT NULL,actor_id TEXT NOT NULL,payload_json TEXT NOT NULL,idempotency_key TEXT NOT NULL,base_state_version INTEGER NOT NULL,prior_digest TEXT NOT NULL,resulting_digest TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,idempotency_key));
CREATE TABLE IF NOT EXISTS state_mutation_candidates(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),source_turn_id TEXT,proposed_by TEXT NOT NULL,operation TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS context_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),workstream_id TEXT,provider_session_id TEXT,draft_hash TEXT NOT NULL,state_version INTEGER NOT NULL,tom_checkpoint_digest TEXT NOT NULL,activation_id TEXT NOT NULL,policy_version TEXT NOT NULL,renderer_version TEXT NOT NULL,selected_json TEXT NOT NULL,excluded_json TEXT NOT NULL,packet_text TEXT NOT NULL,packet_digest TEXT NOT NULL,estimated_tokens INTEGER NOT NULL,latency_ms INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS response_evaluations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),turn_id TEXT NOT NULL,packet_digest TEXT NOT NULL,state_version INTEGER NOT NULL,result TEXT NOT NULL,intervention_ids_json TEXT NOT NULL,policy_version TEXT NOT NULL,latency_ms INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS interventions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),turn_id TEXT NOT NULL,code TEXT NOT NULL,severity TEXT NOT NULL,confidence REAL NOT NULL,summary TEXT NOT NULL,conflicting_state_ids_json TEXT NOT NULL,status TEXT NOT NULL,policy_version TEXT NOT NULL,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS tom_checkpoints(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),state_version INTEGER NOT NULL,checkpoint_digest TEXT NOT NULL,runtime_version TEXT NOT NULL,snapshot_ref TEXT NOT NULL,created_at TEXT NOT NULL,verified_at TEXT);
CREATE TABLE IF NOT EXISTS snapshots(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),state_version INTEGER NOT NULL,state_digest TEXT NOT NULL,tom_checkpoint_digest TEXT NOT NULL,runtime_version TEXT NOT NULL DEFAULT '',schema_versions_json TEXT NOT NULL,archive_path TEXT NOT NULL,state_json TEXT NOT NULL,verified_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(id),category TEXT NOT NULL,correlation_id TEXT NOT NULL,details_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_state_events_project ON state_events(project_id,created_at);
CREATE INDEX IF NOT EXISTS idx_state_objects_project_status ON state_objects(project_id,status,type);
CREATE INDEX IF NOT EXISTS idx_context_runs_project ON context_runs(project_id,created_at);
